CustomField.formula:
MOD(FLOOR((DATETIMEVALUE( 
/* Year Logic */
MID(Actual_Arrival_Date_Time__c, 7,4) +'-'+ 
/* Month Logic */ 
MID(Actual_Arrival_Date_Time__c, 
  FIND("/",Actual_Arrival_Date_Time__c) + 1,
    FIND("/",Actual_Arrival_Date_Time__c, FIND("/",Actual_Arrival_Date_Time__c) + 1) -
    FIND("/",Actual_Arrival_Date_Time__c) - 1
)+'-'+        
/* Day Logic */
LEFT(Actual_Arrival_Date_Time__c, 
  FIND("/",Actual_Arrival_Date_Time__c) - 1) +' '+
/* Time Logic */
    RIGHT(Actual_Arrival_Date_Time__c, 8)
)  -  DATETIMEVALUE( 
/* Year Logic */
MID(Arrival_Date_Time__c, 7,4) +'-'+ 
/* Month Logic */ 
MID(Arrival_Date_Time__c, 
  FIND("/",Arrival_Date_Time__c) + 1,
    FIND("/",Arrival_Date_Time__c, FIND("/",Arrival_Date_Time__c) + 1) -
    FIND("/",Arrival_Date_Time__c) - 1
)+'-'+        
/* Day Logic */
LEFT(Arrival_Date_Time__c, 
  FIND("/",Arrival_Date_Time__c) - 1) +' '+
/* Time Logic */
    RIGHT(Arrival_Date_Time__c, 8)
))*1440),60)
